//! A small crate the indexer is tested against. Every construct here exists to
//! pin one resolution the index must get right: a plain call, a method call
//! whose receiver has to be inferred, a call through a trait object, a call
//! generated by a macro, and a call reached only through a function pointer.

use std::path::Path;

/// A sink the tests look for: it removes a file through the standard library.
pub fn wipe(path: &Path) {
    std::fs::remove_file(path).ok();
}

/// A sink that leaves the file in place, so a reachability test can distinguish
/// the two by name rather than by crate.
pub fn touch(path: &Path) -> bool {
    path.exists()
}

/// Something a trait object dispatches over.
pub trait Store {
    /// Drop whatever the store holds at `path`.
    fn purge(&self, path: &Path);
}

/// A store that really removes the file.
pub struct DiskStore;

/// A store that does not.
pub struct MemoryStore;

impl Store for DiskStore {
    /// Removes the file, so `purge` reaches `wipe` through this implementation.
    fn purge(&self, path: &Path) {
        wipe(path);
    }
}

impl Store for MemoryStore {
    /// Keeps the file, so this implementation reaches no removal.
    fn purge(&self, path: &Path) {
        touch(path);
    }
}

/// Holds a store behind a trait object, which is the case a syntax-only index
/// cannot resolve.
pub struct Engine {
    store: Box<dyn Store>,
}

impl Engine {
    /// Build an engine over the disk store.
    pub fn new() -> Self {
        Engine {
            store: Box::new(DiskStore),
        }
    }

    /// Dispatches through the trait object; the implementation that runs depends
    /// on what `store` really holds.
    pub fn run(&self, path: &Path) {
        self.store.purge(path);
    }

    /// Calls a method whose receiver type has to be inferred from the field.
    pub fn describe(&self) -> String {
        format!("engine over {} stores", self.count())
    }

    /// A method reached only from `describe`, and only through a macro body.
    pub fn count(&self) -> usize {
        1
    }
}

impl Default for Engine {
    /// The default engine is the disk-backed one.
    fn default() -> Self {
        Engine::new()
    }
}

/// Calls through a function pointer, which no index can resolve to a callee.
pub fn indirect(action: fn(&Path), path: &Path) {
    action(path);
}
